    "options": {
      "type": "string",
      "required": true,
      "description": "Array of option strings."
    },
    "value": {
      "type": "string",
      "required": false,
      "description": "Selected value.",
      "default": ""
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called when selection changes."
    },
    "placeholder": {
      "type": "string",
      "required": false,
      "description": "Input placeholder.",
      "default": "Search or select"
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible name of the combobox."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "open",
      "description": "Dropdown is open."
    },
    {
      "name": "closed",
      "description": "Dropdown is closed."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "page",
      "dialog"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use when a simple Select is enough.",
    "Do not filter options without a clear empty state."
  ],
  "a11y": {
    "role": "combobox",
    "keyboard": [
      "Arrow keys move within options",
      "Enter selects"
    ],
    "focus": "Input is focusable; list opens on focus.",
    "labeling": "Visible label prop names the control; ValueText exposes the selection.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Dropdown width matches input.",
    "breakpoints": {
      "compact": "Full width dropdown.",
      "medium": "Input width.",
      "large": "Input width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "combobox",
    "states": [
      "open",
      "closed"
    ],
    "intents": [
      "search-select"
    ]
  }
}

.cu-combobox {
  display: inline-block;
  position: relative;
}

.cu-combobox__label {
  display: block;
  color: var(--cu-color-fg-default);
  font-size: 0.82rem;
  font-weight: 700;
  margin-block-end: var(--cu-space-1);
}

.cu-combobox__control {
  display: inline-flex;
}

.cu-combobox__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cu-space-2);
  min-inline-size: 10rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font: inherit;
  cursor: pointer;
}

.cu-combobox__content {
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  box-shadow: var(--cu-shadow-md, 0 1px 3px color-mix(in srgb, var(--cu-color-background-inverse) 12%, transparent));
  z-index: 10;
}

.cu-combobox__item {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  cursor: pointer;
}

.cu-combobox__item[data-state='checked'] {
  background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
}

.cu-combobox__trigger:focus-visible,
.cu-combobox__item:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
}
